bsp_i2c_status_t bsp_i2c_device_ready(bsp_i2c_device_t *dev,
                                      uint32_t trials,
                                      uint32_t timeout_ms)
{
    if ((dev == NULL) || (dev->bus == NULL) || (dev->bus->hi2c == NULL) || (trials == 0u))
    {
        return BSP_I2C_INVALID_PARAM;
    }
    if (__get_IPSR() != 0U)
    {
        return BSP_I2C_BUSY;
    }

    bsp_i2c_bus_t *bus = dev->bus;
    bsp_i2c_status_t st = bsp_i2c_bus_acquire(dev, timeout_ms);
    if (st != BSP_I2C_OK)
    {
        return st;
    }

    uint32_t ps = __get_PRIMASK(); __disable_irq();
    if (bus->state == BSP_I2C_XFER_BUSY)
    {
        if (!ps) __enable_irq();
        volatile omx_dbg_i2c_t *dbg = bsp_i2c_dbg_of(bus);
        if (dbg != NULL)
        {
            dbg->xfer_busy++;
            bsp_i2c_dbg_capture(dbg, bus, BSP_I2C_BUSY);
        }
        bsp_i2c_bus_release_common(bus);
        return BSP_I2C_BUSY;
    }

    bus->current_dev = dev;
    bus->current_len = 0u;
    bus->last_status = BSP_I2C_BUSY;
    if (!ps) __enable_irq();

    HAL_StatusTypeDef hal_ret =
        HAL_I2C_IsDeviceReady(bus->hi2c,
                              (uint16_t)(dev->addr_7bit << 1),
                              trials,
                              timeout_ms);

    if (hal_ret == HAL_OK)
    {
        st = BSP_I2C_OK;
    }
    else if ((hal_ret == HAL_BUSY) || (hal_ret == HAL_TIMEOUT))
    {
        st = BSP_I2C_BUSY;
    }
    else
    {
        st = BSP_I2C_ERROR;
    }

    ps = __get_PRIMASK(); __disable_irq();
    bus->last_status = st;
    bus->current_dev = NULL;
    bus->current_len = 0u;
    if (!ps) __enable_irq();

    volatile omx_dbg_i2c_t *dbg = bsp_i2c_dbg_of(bus);
    if (dbg != NULL)
    {
        if (st == BSP_I2C_OK)
        {
            dbg->xfer_done++;
        }
        else if (st == BSP_I2C_BUSY)
        {
            dbg->xfer_busy++;
        }
        else
        {
            dbg->xfer_error++;
        }
        dbg->last_dev = (uintptr_t)dev;
        bsp_i2c_dbg_capture(dbg, bus, st);
    }

    bsp_i2c_bus_release_common(bus);
    return st;
}

/**
 * @brief Blocking wrapper for non-blocking APIs.
 */
bsp_i2c_status_t bsp_i2c_wait_complete(bsp_i2c_device_t *dev,
                                       uint32_t timeout_ms)
{
    if (dev == NULL || dev->bus == NULL)
    {
        return BSP_I2C_INVALID_PARAM;
    }

    bsp_i2c_bus_t *bus = dev->bus;
    uint32_t start = HAL_GetTick();
    uint32_t last_yield_tick = start;

    while (bus->state == BSP_I2C_XFER_BUSY)
    {
        uint32_t now = HAL_GetTick();
        if ((now - start) > timeout_ms)
        {
            volatile omx_dbg_i2c_t *dbg = bsp_i2c_dbg_of(bus);
            if (dbg != NULL)
            {
                dbg->xfer_timeout++;
                bsp_i2c_dbg_capture(dbg, bus, BSP_I2C_BUSY);
            }
            (void)bsp_i2c_recover_bus((bsp_i2c_bus_id_t)bsp_i2c_bus_index(bus),
                                       BSP_I2C_RECOVER_REASON_TIMEOUT);
            return BSP_I2C_BUSY;
        }
        bsp_i2c_wait_yield(now, &last_yield_tick);
    }

    return bus->last_status;
}

bsp_i2c_status_t bsp_i2c_is_bus_busy(const bsp_i2c_device_t *dev)
{
    if (dev == NULL || dev->bus == NULL)
    {
        return BSP_I2C_INVALID_PARAM;
    }

    return (dev->bus->state == BSP_I2C_XFER_BUSY) ? BSP_I2C_BUSY : BSP_I2C_OK;
}

bsp_i2c_status_t bsp_i2c_get_snapshot(bsp_i2c_bus_id_t bus_id,
                                      bsp_i2c_snapshot_t *out)
{
    if (out == NULL)
    {
        return BSP_I2C_INVALID_PARAM;
    }

    bsp_i2c_bus_t *bus = bsp_i2c_get_bus_by_id(bus_id);
    if (bus == NULL)
    {
        return BSP_I2C_INVALID_PARAM;
    }

    volatile omx_dbg_i2c_t *dbg = bsp_i2c_dbg_of(bus);
    uint32_t ps = __get_PRIMASK(); __disable_irq();
    out->state = (uint32_t)bus->state;
    out->hal_state = bus->hi2c ? (uint32_t)HAL_I2C_GetState(bus->hi2c) : 0u;
    out->hal_error = bus->hi2c ? (uint32_t)HAL_I2C_GetError(bus->hi2c) : 0u;
    out->lock_held = bus->lock_held;
    out->lock_owner = (uintptr_t)bus->lock_owner;
    out->current_dev = (uintptr_t)bus->current_dev;
    out->current_len = (uint32_t)bus->current_len;
    out->last_status = (uint32_t)bus->last_status;
    out->last_tick = HAL_GetTick();
    out->recover_count = dbg ? dbg->recover_count : 0u;
    out->cb_queued = bsp_i2c_cb_queue_depth();
    out->cb_queue_overflow = dbg ? dbg->cb_queue_overflow : 0u;
    if (!ps) __enable_irq();

    return BSP_I2C_OK;
}

bsp_i2c_status_t bsp_i2c_recover_bus(bsp_i2c_bus_id_t bus_id,
                                     uint32_t reason)
{
    if (__get_IPSR() != 0U)
    {
        return BSP_I2C_BUSY;
    }

    bsp_i2c_bus_t *bus = bsp_i2c_get_bus_by_id(bus_id);
    if ((bus == NULL) || (bus->hi2c == NULL))
    {
        return BSP_I2C_INVALID_PARAM;
    }

    volatile omx_dbg_i2c_t *dbg = bsp_i2c_dbg_of(bus);

    uint16_t dev_addr = 0u;
    if (bus->current_dev != NULL)
    {
        dev_addr = (uint16_t)(bus->current_dev->addr_7bit << 1);
    }
    HAL_StatusTypeDef abort_st = HAL_I2C_Master_Abort_IT(bus->hi2c, dev_addr);

    uint32_t ps = __get_PRIMASK(); __disable_irq();
    bus->last_status = BSP_I2C_ERROR;
    bsp_i2c_clear_xfer(bus);
    if (dbg != NULL)
    {
        dbg->recover_count++;
        dbg->last_recover_reason = reason;
        dbg->h.last_tick = HAL_GetTick();
        dbg->state = bus->state;
        dbg->hal_state = (uint32_t)HAL_I2C_GetState(bus->hi2c);
        dbg->hal_error = (uint32_t)HAL_I2C_GetError(bus->hi2c);
        if (abort_st != HAL_OK)
        {
            dbg->recover_error++;
        }
    }
    if (!ps) __enable_irq();

    bsp_i2c_bus_release_common(bus);
    return (abort_st == HAL_OK) ? BSP_I2C_OK : BSP_I2C_ERROR;
}

/* ----------------------------------------------------------------------
 * HAL callbacks.
 *
 * These callbacks are called from HAL I2C IRQ context.
 * We translate them to BSP-level logic and then call user callbacks.
 * -------------------------------------------------------------------- */

static void bsp_i2c_on_complete(I2C_HandleTypeDef *hi2c, bsp_i2c_status_t status)
{
    bsp_i2c_bus_t *bus = bsp_i2c_get_bus_by_handle(hi2c);
    if (bus == NULL)
    {
        return;
    }

    bsp_i2c_device_t *dev = bus->current_dev;
    bsp_i2c_callback_t cb = bus->current_cb;
    void *ctx = bus->current_cb_ctx;

    if (status == BSP_I2C_OK)
    {
        bsp_i2c_copy_rx_if_needed(bus);
    }
    bus->last_status = status;
    volatile omx_dbg_i2c_t *dbg = bsp_i2c_dbg_of(bus);
    if (dbg != NULL)
    {
        if (status == BSP_I2C_OK)
        {
            dbg->xfer_done++;
        }
        else
        {
            dbg->xfer_error++;
        }
        bsp_i2c_dbg_capture(dbg, bus, status);
        dbg->cb_status = (uint32_t)status;
        dbg->last_dev = (uintptr_t)dev;
    }

    bsp_i2c_clear_xfer(bus);
    bsp_i2c_bus_release_common(bus);

    (void)bsp_i2c_cb_enqueue(dev, cb, ctx, status);
}

void HAL_I2C_MasterTxCpltCallback(I2C_HandleTypeDef *hi2c)
{
    bsp_i2c_on_complete(hi2c, BSP_I2C_OK);
}

void HAL_I2C_MasterRxCpltCallback(I2C_HandleTypeDef *hi2c)
{
    bsp_i2c_on_complete(hi2c, BSP_I2C_OK);
}

void HAL_I2C_MemTxCpltCallback(I2C_HandleTypeDef *hi2c)
{
    bsp_i2c_on_complete(hi2c, BSP_I2C_OK);
}

void HAL_I2C_MemRxCpltCallback(I2C_HandleTypeDef *hi2c)
{
    bsp_i2c_on_complete(hi2c, BSP_I2C_OK);
}

void HAL_I2C_ErrorCallback(I2C_HandleTypeDef *hi2c)
{
    bsp_i2c_on_complete(hi2c, BSP_I2C_ERROR);
}
